  const m = base.length
  const n = side.length
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Array(n + 1).fill(0)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (base[i] === side[j]) dp[i][j] = dp[i + 1][j + 1] + 1
      else dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }
  return dp
}

/**
 * Walk base and side from the start, taking a match whenever the current
 * lines are equal and otherwise advancing whichever side keeps at least as
 * long a remaining common subsequence available, preferring to advance the
 * base on a tie. Returns the list of matched [baseIndex, sideIndex] pairs.
 */
function alignForward(base, side, dp) {
  const matches = []
  let i = 0
  let j = 0
  while (i < base.length && j < side.length) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Diff a side against the base: every stretch the alignment does not cover
 * becomes a change, a run of base lines replaced by a run of the side's
 * lines.
 */
export function diffAgainstBase(base, side) {
  const dp = suffixLcsLengths(base, side)
  const matches = alignForward(base, side, dp)
  const changes = []
  let baseCursor = 0
  let sideCursor = 0
  for (const [bi, si] of matches) {
    if (bi > baseCursor || si > sideCursor) {
      changes.push({
        baseStart: baseCursor,
        baseEnd: bi,
        sideStart: sideCursor,
        sideEnd: si,
      })
    }
    baseCursor = bi + 1
    sideCursor = si + 1
  }
  if (baseCursor < base.length || sideCursor < side.length) {
    changes.push({
      baseStart: baseCursor,
      baseEnd: base.length,
      sideStart: sideCursor,
      sideEnd: side.length,
    })
  }
  return changes
}

/**
 * Merge the changes from both sides into one list ordered by where they
 * start in the base, with mine's changes before theirs's at the same start.
 */
function orderChanges(mineChanges, theirsChanges) {
  const tagged = [
    ...mineChanges.map(change => ({ ...change, side: 'mine' })),
    ...theirsChanges.map(change => ({ ...change, side: 'theirs' })),
  ]
  tagged.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })
  return tagged
