    const first = changes[i]
    let regionStart = first.baseStart
    let regionEnd = first.baseEnd
    const touching = [first]
    i++
    while (i < changes.length && changes[i].baseStart <= regionEnd) {
      regionEnd = Math.max(regionEnd, changes[i].baseEnd)
      touching.push(changes[i])
      i++
    }
    regions.push({ baseStart: regionStart, baseEnd: regionEnd, touching })
  }
