/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { buildMergePlan } from './diff3.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitDocuments(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const documents = [[]]
  for (const line of lines) {
    if (line === '%%%') documents.push([])
    else documents[documents.length - 1].push(line)
  }
  if (documents.length !== 3) fail('expected three parts separated by %%%')
  return documents
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', chunk => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function renderMerge(parts, withBase) {
  const lines = []
  let conflict = false
  for (const part of parts) {
    if (part.type === 'stable') {
      lines.push(...part.lines)
      continue
    }
    if (part.kind === 'conflict') {
      conflict = true
      lines.push('<<<<<<< mine')
      lines.push(...part.mineSlice)
      if (withBase) {
        lines.push('||||||| base')
        lines.push(...part.baseSlice)
      }
      lines.push('=======')
      lines.push(...part.theirsSlice)
      lines.push('>>>>>>> theirs')
    } else if (part.kind === 'theirs') {
      lines.push(...part.theirsSlice)
    } else {
      lines.push(...part.mineSlice)
    }
  }
  return { lines, conflict }
}

function renderRegions(parts) {
  const lines = []
  let conflict = false
  for (const part of parts) {
    if (part.type === 'stable') {
      lines.push(`stable ${part.lines.length}`)
      continue
    }
    if (part.kind === 'conflict') {
      conflict = true
      lines.push(`conflict mine=${part.mineSlice.length} base=${part.baseSlice.length} theirs=${part.theirsSlice.length}`)
    } else if (part.kind === 'both') {
      lines.push(`both ${part.mineSlice.length}`)
    } else if (part.kind === 'theirs') {
      lines.push(`theirs ${part.theirsSlice.length}`)
    } else {
      lines.push(`mine ${part.mineSlice.length}`)
    }
  }
  return { lines, conflict }
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('usage: cli.js merge|merge2|regions')
  }

  const text = await readStdin()
  const [mine, base, theirs] = splitDocuments(text)
  const parts = buildMergePlan(mine, base, theirs)

  let result
  if (mode === 'merge') result = renderMerge(parts, true)
  else if (mode === 'merge2') result = renderMerge(parts, false)
  else result = renderRegions(parts)

  process.stdout.write(result.lines.map(line => `${line}\n`).join(''))
  process.exit(result.conflict ? 1 : 0)
}

main()
